SELECT ANY_VALUE(user_name) AS NAME, COUNT(1) AS VALUE FROM cc_group_user_rel WHERE user_type = 2
AND create_time > #{biDTO.startTime} AND create_time < #{biDTO.endTime}
GROUP BY user_hash

SELECT ANY_VALUE(user_name) AS NAME, AVG(star_level) AS VALUE FROM cc_group_user_rel WHERE user_type = 2
AND create_time > #{biDTO.startTime} AND create_time < #{biDTO.endTime}
GROUP BY user_hash
